package az.achiqyol.config;
import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.web.SecurityFilterChain; import org.springframework.security.core.userdetails.*; import org.springframework.security.provisioning.InMemoryUserDetailsManager; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.web.cors.*; import org.springframework.http.HttpMethod; import java.util.List; import static org.springframework.security.config.Customizer.withDefaults;
@Configuration public class SecurityConfig { @Bean UserDetailsService users(@Value("${app.admin-user}") String user,@Value("${app.admin-password}") String password) { return new InMemoryUserDetailsManager(User.withUsername(user).password(new BCryptPasswordEncoder().encode(password)).roles("ADMIN").build()); }
@Bean org.springframework.security.crypto.password.PasswordEncoder encoder() { return new BCryptPasswordEncoder(); }
@Bean SecurityFilterChain security(HttpSecurity http) throws Exception { return http.cors(withDefaults()).csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers(HttpMethod.GET,"/**").permitAll().anyRequest().hasRole("ADMIN")).httpBasic(withDefaults()).build(); }
@Bean CorsConfigurationSource cors(@Value("${app.cors-origins}") String origins) { var c=new CorsConfiguration(); c.setAllowedOrigins(List.of(origins.split(","))); c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS")); c.setAllowedHeaders(List.of("Content-Type","Authorization")); var source=new UrlBasedCorsConfigurationSource(); source.registerCorsConfiguration("/**",c); return source; } }
